function isBinaryContent(buffer) {
  const sampleSize = Math.min(buffer.length, 8192);
  for (let i = 0; i < sampleSize; i++) {
    const byte = buffer[i];
    if (byte === 0) return true;
    if (byte < 32 && byte !== 9 && byte !== 10 && byte !== 13) return true;
  }
  return false;
}
function getMimeType(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  const mimeTypes = {
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".gif": "image/gif",
    ".webp": "image/webp",
    ".svg": "image/svg+xml",
    ".pdf": "application/pdf",
    ".html": "text/html",
    ".htm": "text/html",
    ".css": "text/css",
    ".js": "application/javascript",
    ".json": "application/json",
    ".txt": "text/plain"
  };
  return mimeTypes[ext] || "application/octet-stream";
}
function bufferToDataUri(buffer, mimeType) {
  const base64 = buffer.toString("base64");
  return `data:${mimeType};base64,${base64}`;
}
async function executeProfileSetCanvas(options) {
  if (!options.file && !options.content) {
    exitWithError(
      "Must provide either --file or --content to set canvas content."
    );
  }
  if (options.file && options.content) {
    exitWithError("Cannot provide both --file and --content. Choose one.");
  }
  let canvasContent;
  if (options.file) {
    const filePath = path.resolve(options.file);
    if (!fs6.existsSync(filePath)) {
      exitWithError(`File not found: ${filePath}`);
    }
    const buffer = fs6.readFileSync(filePath);
    if (buffer.length > MAX_CANVAS_SIZE) {
      exitWithError(
        `File too large: ${buffer.length} bytes exceeds maximum of ${MAX_CANVAS_SIZE} bytes (60KB).`
      );
    }
    if (isBinaryContent(buffer)) {
      const mimeType = getMimeType(filePath);
      canvasContent = bufferToDataUri(buffer, mimeType);
    } else {
      canvasContent = buffer.toString("utf-8");
    }
  } else {
    canvasContent = options.content;
    const contentSize = Buffer.byteLength(canvasContent, "utf-8");
    if (contentSize > MAX_CANVAS_SIZE) {
      exitWithError(
        `Content too large: ${contentSize} bytes exceeds maximum of ${MAX_CANVAS_SIZE} bytes (60KB).`
      );
    }
  }
  const bytesKey = toBytes32(PROFILE_CANVAS_STORAGE_KEY);
  const chunks = chunkDataForStorage(canvasContent);
  if (options.encodeOnly) {
    const readOnlyOptions = parseReadOnlyOptions({
      chainId: options.chainId,
      rpcUrl: options.rpcUrl
    });
    const encoded = encodeTransaction(
      {
        to: CHUNKED_STORAGE_CONTRACT.address,
        abi: CHUNKED_STORAGE_CONTRACT.abi,
        functionName: "put",
        args: [bytesKey, CANVAS_FILENAME, chunks]
      },
      readOnlyOptions.chainId
    );
    console.log(JSON.stringify(encoded, null, 2));
    return;
  }
  const commonOptions = parseCommonOptions(
    {
      privateKey: options.privateKey,
      chainId: options.chainId,
      rpcUrl: options.rpcUrl
    },
    true
    // supports --encode-only
  );
  try {
    const account = privateKeyToAccount(commonOptions.privateKey);
    const rpcUrls = getChainRpcUrls({
      chainId: commonOptions.chainId,
      rpcUrl: commonOptions.rpcUrl
    });
    const client = createWalletClient({
      account,
      chain: base,
      // TODO: Support other chains
      transport: http(rpcUrls[0])
    }).extend(publicActions);
    console.log(chalk4.blue(`Setting profile canvas...`));
    console.log(
      chalk4.gray(`   Content size: ${Buffer.byteLength(canvasContent)} bytes`)
    );
    console.log(chalk4.gray(`   Chunks: ${chunks.length}`));
    console.log(chalk4.gray(`   Address: ${account.address}`));
    const hash = await client.writeContract({
      address: CHUNKED_STORAGE_CONTRACT.address,
      abi: CHUNKED_STORAGE_CONTRACT.abi,
      functionName: "put",
      args: [bytesKey, CANVAS_FILENAME, chunks]
    });
    console.log(chalk4.blue(`Waiting for confirmation...`));
    const receipt = await client.waitForTransactionReceipt({ hash });
    if (receipt.status === "success") {
      console.log(
        chalk4.green(
          `
Canvas updated successfully!
  Transaction: ${hash}
  Content size: ${Buffer.byteLength(canvasContent)} bytes
  Chunks: ${chunks.length}`
        )
      );
    } else {
      exitWithError(`Transaction failed: ${hash}`);
    }
  } catch (error) {
    exitWithError(
      `Failed to set canvas: ${error instanceof Error ? error.message : String(error)}`
    );
  }
}
function isDataUri(content) {
  return content.startsWith("data:");
}
function parseDataUri(dataUri) {
  const match = dataUri.match(/^data:([^;]+);base64,(.+)$/);
  if (!match) {
    throw new Error("Invalid data URI format");
  }
  const mimeType = match[1];
  const base64Data = match[2];
  const buffer = Buffer.from(base64Data, "base64");
  return { buffer, mimeType };
}
function getExtensionFromMimeType(mimeType) {
  const extensions = {
    "image/png": ".png",
    "image/jpeg": ".jpg",
    "image/gif": ".gif",
    "image/webp": ".webp",
    "image/svg+xml": ".svg",
    "application/pdf": ".pdf",
    "text/html": ".html",
    "text/css": ".css",
    "application/javascript": ".js",
    "application/json": ".json",
    "text/plain": ".txt",
    "application/octet-stream": ".bin"
  };
  return extensions[mimeType] || ".bin";
}
async function executeProfileGetCanvas(options) {
  const readOnlyOptions = parseReadOnlyOptions({
    chainId: options.chainId,
    rpcUrl: options.rpcUrl
  });
  const client = new StorageClient({
    chainId: readOnlyOptions.chainId,
    overrides: options.rpcUrl ? { rpcUrls: [options.rpcUrl] } : void 0
  });
  try {
    let canvasContent;
    let canvasText;
    try {
      const result = await client.readChunkedStorage({
        key: PROFILE_CANVAS_STORAGE_KEY,
        operator: options.address
      });
      if (result.data) {
        canvasContent = result.data;
        canvasText = result.text;
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      if (errorMessage !== "ChunkedStorage metadata not found" && !errorMessage.includes("not found")) {
        throw error;
      }
    }
    if (options.json) {
      const output = {
        address: options.address,
        chainId: readOnlyOptions.chainId,
        canvas: canvasContent || null,
        filename: canvasText || null,
        hasCanvas: !!canvasContent,
        isDataUri: canvasContent ? isDataUri(canvasContent) : false,
        contentLength: canvasContent ? canvasContent.length : 0
      };
      console.log(JSON.stringify(output, null, 2));
      return;
    }
    if (!canvasContent) {
      exitWithError(`No canvas found for address: ${options.address}`);
    }
    if (options.output) {
      const outputPath = path.resolve(options.output);
      if (isDataUri(canvasContent)) {
        const { buffer, mimeType } = parseDataUri(canvasContent);
        let finalPath = outputPath;
        if (!path.extname(outputPath)) {
          finalPath = outputPath + getExtensionFromMimeType(mimeType);
        }
        fs6.writeFileSync(finalPath, buffer);
        console.log(
          chalk4.green(`Canvas written to: ${finalPath} (${buffer.length} bytes)`)
        );
      } else {
        fs6.writeFileSync(outputPath, canvasContent, "utf-8");
        console.log(
          chalk4.green(
            `Canvas written to: ${outputPath} (${canvasContent.length} bytes)`
          )
        );
      }
      return;
    }
    console.log(canvasContent);
  } catch (error) {
    exitWithError(
      `Failed to read canvas: ${error instanceof Error ? error.message : String(error)}`
    );
  }
}
async function executeProfileSetCSS(options) {
  const sourceCount = [options.file, options.content, options.theme].filter(
    Boolean
  ).length;
  if (sourceCount === 0) {
    exitWithError(
      "Must provide one of --file, --content, or --theme to set CSS."
    );
  }
  if (sourceCount > 1) {
    exitWithError("Cannot provide more than one of --file, --content, --theme.");
  }
  let cssContent;
  if (options.theme) {
    const theme = DEMO_THEMES[options.theme];
    if (!theme) {
      const available = Object.entries(DEMO_THEMES).map(([key, val]) => `  ${key} \u2014 ${val.name}`).join("\n");
      exitWithError(
        `Unknown theme: "${options.theme}"

Available themes:
${available}`
      );
    }
    cssContent = theme.css;
    console.log(chalk4.gray(`   Using theme: ${theme.name}`));
  } else if (options.file) {
    const filePath = path.resolve(options.file);
    if (!fs6.existsSync(filePath)) {
      exitWithError(`File not found: ${filePath}`);
    }
    const buffer = fs6.readFileSync(filePath);
    if (buffer.length > MAX_CSS_SIZE) {
      exitWithError(
        `File too large: ${buffer.length} bytes exceeds maximum of ${MAX_CSS_SIZE} bytes (10KB).`
      );
    }
    cssContent = buffer.toString("utf-8");
  } else {
    cssContent = options.content;
    const contentSize = Buffer.byteLength(cssContent, "utf-8");
    if (contentSize > MAX_CSS_SIZE) {
      exitWithError(
        `Content too large: ${contentSize} bytes exceeds maximum of ${MAX_CSS_SIZE} bytes (10KB).`
      );
    }
  }
  if (!isValidCSS(cssContent)) {
    exitWithError(
      "Invalid CSS: content is empty, too large, or contains disallowed patterns (script injection)."
    );
  }
  const storageArgs = getProfileCSSStorageArgs(cssContent);
  if (options.encodeOnly) {
    const readOnlyOptions = parseReadOnlyOptions({
      chainId: options.chainId,
      rpcUrl: options.rpcUrl
    });
    const encoded = encodeTransaction(
      {
        to: STORAGE_CONTRACT.address,
        abi: STORAGE_CONTRACT.abi,
        functionName: "put",
        args: [storageArgs.bytesKey, storageArgs.topic, storageArgs.bytesValue]
      },
      readOnlyOptions.chainId
    );
    console.log(JSON.stringify(encoded, null, 2));
    return;
  }
  const commonOptions = parseCommonOptions(
    {
      privateKey: options.privateKey,
      chainId: options.chainId,
      rpcUrl: options.rpcUrl
    },
    true
  );
  try {
    const account = privateKeyToAccount(commonOptions.privateKey);
    const rpcUrls = getChainRpcUrls({
      chainId: commonOptions.chainId,
      rpcUrl: commonOptions.rpcUrl
    });
    const client = createWalletClient({
      account,
      chain: base,
      transport: http(rpcUrls[0])
    }).extend(publicActions);
    console.log(chalk4.blue(`Setting profile CSS...`));
    console.log(
      chalk4.gray(
        `   Content size: ${Buffer.byteLength(cssContent, "utf-8")} bytes`
      )
    );
    console.log(chalk4.gray(`   Address: ${account.address}`));
    const hash = await client.writeContract({
      address: STORAGE_CONTRACT.address,
      abi: STORAGE_CONTRACT.abi,
      functionName: "put",
      args: [storageArgs.bytesKey, storageArgs.topic, storageArgs.bytesValue]
    });
    console.log(chalk4.blue(`Waiting for confirmation...`));
    const receipt = await client.waitForTransactionReceipt({ hash });
    if (receipt.status === "success") {
      console.log(
        chalk4.green(
          `
CSS updated successfully!
  Transaction: ${hash}
  Content size: ${Buffer.byteLength(cssContent, "utf-8")} bytes`
        )
      );
    } else {
      exitWithError(`Transaction failed: ${hash}`);
    }
  } catch (error) {
    exitWithError(
      `Failed to set CSS: ${error instanceof Error ? error.message : String(error)}`
    );
  }
}
async function executeProfileGetCSS(options) {
  const readOnlyOptions = parseReadOnlyOptions({
    chainId: options.chainId,
    rpcUrl: options.rpcUrl
  });
  const client = new StorageClient({
    chainId: readOnlyOptions.chainId,
    overrides: options.rpcUrl ? { rpcUrls: [options.rpcUrl] } : void 0
  });
  try {
    let cssContent;
    try {
      const result = await client.readStorageData({
        key: PROFILE_CSS_STORAGE_KEY,
        operator: options.address
      });
      if (result.data) {
        cssContent = result.data;
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      if (errorMessage !== "StoredDataNotFound") {
        throw error;
      }
    }
    if (options.json) {
      const output = {
        address: options.address,
        chainId: readOnlyOptions.chainId,
        css: cssContent || null,
        hasCSS: !!cssContent,
        contentLength: cssContent ? cssContent.length : 0
      };
      console.log(JSON.stringify(output, null, 2));
      return;
    }
    if (!cssContent) {
      exitWithError(`No custom CSS found for address: ${options.address}`);
    }
    if (options.output) {
      const outputPath = path.resolve(options.output);
      fs6.writeFileSync(outputPath, cssContent, "utf-8");
      console.log(
        chalk4.green(
          `CSS written to: ${outputPath} (${cssContent.length} bytes)`
        )
      );
      return;
    }
    console.log(cssContent);
  } catch (error) {
    exitWithError(
      `Failed to read CSS: ${error instanceof Error ? error.message : String(error)}`
    );
  }
}
async function executeProfileCSSPrompt(options) {
  if (options.listThemes) {
    console.log("Available demo themes:\n");
    for (const [key, theme] of Object.entries(DEMO_THEMES)) {
      console.log(`  ${key} \u2014 ${theme.name}`);
    }
    console.log(
      "\nUse with: net profile set-css --theme <name>"
    );
    return;
  }
  console.log(buildCSSPrompt());
}

